from c8e_base import *
# ---- Unit 2 lesson 1: A Tale of Valour
LB(8,2,'Language work: army expressions, over- verbs, noun-verb pairs and an enquiry letter','Language work for A Tale of Valour: expressions, over- verbs, c/s pairs and a letter of enquiry','Words from the battlefield',
 "A story of courage in Kashmir gives us strong expressions about defence, words that begin with over-, pairs of words that differ by one letter, and a way of writing to a place you wish to visit.",
 [("Some expressions describe action under pressure. To fight to the last man is to fight until every soldier has given his life. To foil a plan is to stop it from working, to hold their ground is to stay in position and fight back even when the enemy is stronger, and to deliver a blow is to strike hard at something.","fight to the last man, foil the plan, hold their ground, deliver a blow"),
  ("Use these in your own sentences. A detective can foil a culprit's plan by finding hidden evidence, and hikers can hold their ground in heavy rain by refusing to turn back.","using expressions"),
  ("Collective nouns name groups. A squadron is a small unit of about 12 to 24 aircraft with their crews, and a fleet is a group of ships sailing together. A regiment and a battalion are army units of soldiers, so check a dictionary for how they are organised.","squadron, fleet, regiment, battalion"),
  ("Many verbs begin with over-. To overthrow is to take and seize control. To overrun is to invade or occupy an area in large numbers. To overwhelm is to flood or overpower, often emotionally.","overthrow, overrun, overwhelm"),
  ("Some words differ by one letter, and the letter tells the part of speech. In advice, practice, device and council the letter c shows a noun. In advise, practise, devise and counsel the letter s shows a verb.","c for nouns, s for verbs"),
  ("So we say 'her advice is helpful' and 'she will advise students', 'daily practice helps' and 'she will practise her lessons'.","advice/advise, practice/practise"),
  ("A letter of enquiry is a formal letter seeking detailed information, for example about joining a course or visiting a place. Use formal, specific language and a clear layout.","letter of enquiry"),
  ("To write to the in-charge of a memorial, ask about the dates available for visits, the duration of the tour, any entry fee, and guidelines for student groups, and end with a polite request for a reply.","what to ask in the letter")],
 ("Fill in the blanks: (a) The teacher's ___ is always helpful and she will ___ students. (b) Soldiers outnumbered by the enemy chose to ___ their ground.",
  [("(a) advice (noun, after 'The teacher's') and advise (verb, after 'will').","c is for the noun and s for the verb."),
   ("(b) hold their ground, meaning stay in position and fight back.","Use the expression that means standing firm.")]),
 ("Explain how to tell advice from advise, and list four things a letter of enquiry about a memorial visit should ask.",
  ["advice is a noun with c; advise is a verb with s","Dates available for visits","Duration of the tour, entry fee and guidelines for student groups"],
  ["Using advice and advise as if they are the same word","Writing the enquiry letter in informal language"]),
 ["Expressions: fight to the last man, foil a plan, hold their ground, deliver a blow.","overthrow, overrun and overwhelm have different meanings.","c for nouns, s for verbs: advice/advise, practice/practise, device/devise, council/counsel.","A letter of enquiry is formal and asks specific questions."],
 [mcq("v1-1",1,"To 'foil a plan' means to","stop it from working",[("carry it out quickly","That is the opposite."),("hide it from others","Foiling is stopping, not hiding.")],"Foil means prevent from succeeding."),
  mcq("v1-2",1,"'Hold their ground' means to","stay in position and fight back",[("run away","That is retreating."),("surrender","Holding means not giving way.")],"They did not give way."),
  mcq("v1-3",1,"A group of ships sailing together is a","fleet",[("squadron","A squadron is a unit of aircraft."),("council","A council is a group that makes decisions.")],"Fleet is the collective noun for ships."),
  mcq("v1-4",2,"'To invade or occupy an area in large numbers' is to","overrun",[("overthrow","This means to seize control."),("overwhelm","This means to overpower, often emotionally.")],"overrun."),
  mcq("v1-5",2,"The teacher's ___ is helpful.","advice",[("advise","Advise is the verb."),("advices","Advice has no usual plural form.")],"A noun is needed, so use c."),
  short("v1-6",2,"What is the verb form of 'device'? (one word)",["devise"],"device (noun) and devise (verb)."),
  tf("v1-7",2,"In advice and advise, the letter c shows the noun and s shows the verb.",True,"This is the pattern for these pairs."),
  mcq("v1-8",3,"A letter of enquiry is","a formal letter that asks for detailed information",[("a personal letter to a friend","It is formal."),("a letter of complaint","It asks for information.")],"Formal and specific."),
  mcq("v1-9",3,"Which would you NOT ask in a letter of enquiry about a memorial visit?","the writer's favourite food",[("entry fees","Useful to ask."),("dates for visits","Useful to ask.")],"Ask only relevant information.")])
# ---- Unit 2 lesson 2: Somebody's Mother
LB(8,2,'Language work: words in context, hand idioms, lest and a diary entry','Language work for Somebody\'s Mother: words in context, idioms with hand, lest and diary writing','Lending a hand',
 "A poem about a boy who helps an old woman cross a busy street teaches us verbs that describe helping, idioms with the word hand, a small word that warns, and the way to write a diary.",
 [("Words from the poem have simple everyday meanings. Hastened means worked quickly, heeded means paid attention to, stir means move slightly, lend means give support, piled means kept in a heap, and offered can mean came forward to help.","hastened, heeded, stir, lend, piled, offered"),
  ("The idiom lend a hand means help somebody. Other idioms use hand too. If a situation gets out of hand it becomes difficult to control, and if you try your hand at something you do something new.","lend a hand, get out of hand, try your hand at"),
  ("To give somebody a free hand is to allow full freedom to act, and to give somebody a big hand is to applaud. To work hand in hand is to work together, and to have your hands full is to be very busy.","free hand, big hand, hand in hand, hands full"),
  ("Lest is a conjunction meaning to prevent something bad from happening. You can replace it with just in case, as in 'She showed all the documents lest we doubt her'.","lest = just in case"),
  ("Analogies show a pair relationship: heat is to summer as cold is to winter, and hurt is to injured as old is to aged. Find the relationship first, then apply it to the second pair.","analogies"),
  ("The -ed ending has three sounds. After t or d it is pronounced /id/, as in waited and heeded. After voiceless sounds like p, k and s it is /t/, and after most other sounds it is /d/, as in whispered and offered. An adjective like aged or ragged before a noun uses /id/.","pronouncing -ed"),
  ("A diary entry is personal. Start with the date and day, then write Dear Diary. Describe the day, whom you helped and the situation, the place and time, how you helped, their reaction and how you felt, and say whether you would do it again.","writing a diary entry")],
 ("Use idioms to complete: (a) The teacher gave the students a free ___ to design the show. (b) When the crowd began to push, the situation got out of ___. (c) After the dance the audience gave the performers a big ___.",
  [("(a) hand: to give a free hand means to allow full freedom.","Match the idiom to its meaning."),
   ("(b) hand: to get out of hand means to become difficult to control.","The crowd was hard to control."),
   ("(c) hand: to give a big hand means to applaud.","The audience applauded.")]),
 ("Explain what 'lest' means and give the three sounds of the -ed ending with one example for each.",
  ["lest means to prevent something bad and can be replaced by just in case","/id/ after t or d: waited","/t/ after voiceless sounds and /d/ after most other sounds: whispered"],
  ["Thinking -ed is always pronounced the same way","Using lest to mean 'because'"]),
 ["Hastened, heeded, stir, lend, piled and offered have everyday meanings.","Idioms with hand: lend a hand, get out of hand, try your hand at, a free hand, a big hand, hand in hand, hands full.","Lest means just in case something bad happens.","-ed has three sounds: /id/, /t/ and /d/."],
 [mcq("v2-1",1,"'Heeded' means","paid attention to",[("worked quickly","That is hastened."),("moved slightly","That is stir.")],"They heeded our advice means they paid attention to it."),
  mcq("v2-2",1,"The idiom 'lend a hand' means","help somebody",[("applaud somebody","That is give a big hand."),("do something new","That is try your hand at.")],"Lend a hand is to help."),
  mcq("v2-3",1,"If a situation 'gets out of hand' it","becomes difficult to control",[("is very busy","That is have your hands full."),("is applauded","That is give a big hand.")],"It slips out of control."),
  mcq("v2-4",2,"'To work hand in hand' means to","work together",[("be very busy","That is have your hands full."),("allow freedom","That is give a free hand.")],"They work together."),
  mcq("v2-5",2,"'She showed all the documents lest we doubt her' means she showed them","just in case we doubted her",[("because we asked","Lest is not 'because'."),("after we doubted her","Lest prevents a doubt.")],"Lest means to prevent something bad."),
  mcq("v2-6",2,"The -ed in 'waited' is pronounced","/id/",[("/d/","/d/ is heard in whispered."),("/t/","/t/ is heard after sounds like p or k.")],"After t or d the ending is /id/."),
  tf("v2-7",2,"To 'have your hands full' means to be very busy.",True,"Hands full means busy."),
  mcq("v2-8",3,"Which should a diary entry NOT include?","a formal address to an official",[("the date and day","Diaries start with a date."),("how you felt","Feelings belong in a diary.")],"A diary is personal, not a formal letter."),
  mcq("v2-9",3,"The -ed in 'whispered' is pronounced","/d/",[("/id/","/id/ is used after t or d."),("/t/","/t/ is used after voiceless sounds.")],"The r sound before -ed gives /d/.")])
# ---- Unit 2 lesson 3: Verghese Kurien
LB(8,2,'Language work: synonyms, expressions, dashes, syllable stress and a thank-you letter','Language work for I Too Had a Dream: synonyms, expressions, dashes, stress and a letter of thanks','Hold your head high',
 "Dr Verghese Kurien's story carries phrases about humility and effort. This lesson looks at words that mean almost the same, expressions about character, two kinds of dash, how stress changes a word from a noun to a verb, and how to write a letter of thanks.",
 [("Synonyms are words with nearly the same meaning. Magnificent is splendid, fleeting is momentary, instant is swift, core is essential, valuable is useful, and abiding is lifelong. A synonym must also fit the sentence.","synonyms"),
  ("In all humility means being humble with no feeling of self-importance. To hold their heads high is to be confident and have a positive feeling. To be quite honest is to speak in a truthful way.","in all humility, hold their heads high, to be quite honest"),
  ("To the best of your ability means using all your skills, talents and knowledge. Looked at in awe means observed with great respect and wonder, and somewhere deep down means in the innermost part of the self.","to the best of your ability, in awe, deep down"),
  ("The en dash is the shorter dash and shows a span or range, as in train operates June–September, refer to pages 50–75 and India won the series 2–1.","en dash for a range"),
  ("The em dash is the longer dash. It adds extra information or shows a change in thought, as in 'The exhibition—held in the main hall—features local artists'. Do not put spaces around a dash and do not overuse it.","em dash for extra information"),
  ("Some words change stress when they change part of speech. A noun usually has the stress on the first syllable, PREsent, and a verb on the second, preSENT. In the same way PROduce is a noun and proDUCE a verb, CONtract is a noun and conTRACT a verb, and PROject is a noun and proJECT a verb.","stress shift: noun and verb"),
  ("A letter of thanks to grandparents should thank them for the lessons and stories they shared, say how their wisdom has shaped your values and behaviour, and share how their actions inspire you to do something good for society.","letter of thanks")],
 ("Insert the right dash: (a) The conference will be held from March 15 ___ March 20. (b) The artist ___ known for her vibrant paintings ___ will show her work in Guwahati. Then mark the stress in the noun and verb forms of 'project'.",
  [("(a) March 15–March 20 uses an en dash because it shows a range of dates.","A range uses the en dash."),
   ("(b) The artist—known for her vibrant paintings—will show her work in Guwahati uses em dashes to add extra information.","Extra information inside a sentence uses the em dash."),
   ("The noun is PROject with stress on the first syllable and the verb is proJECT with stress on the second.","Noun: first syllable; verb: second syllable.")]),
 ("Explain the difference between an en dash and an em dash with one example each, and say which syllable is stressed in the verb 'present'.",
  ["en dash: a range such as June–September","em dash: extra information or a change in thought","The verb preSENT has stress on the second syllable"],
  ["Using spaces around dashes","Using only a hyphen for ranges"]),
 ["Synonyms: magnificent-splendid, fleeting-momentary, valuable-useful.","En dash shows a range; em dash adds extra information.","Noun stress is on the first syllable and verb stress on the second: PRESent/preSENT.","A thank-you letter names the lessons learnt and how they shaped you."],
 [mcq("v3-1",1,"A synonym of 'fleeting' is","momentary",[("lifelong","This is abiding."),("essential","This is core.")],"Fleeting means lasting a very short time."),
  mcq("v3-2",1,"'In all humility' means","being humble with no feeling of self-importance",[("speaking in a truthful way","This is to be quite honest."),("using all your skills","This is to the best of your ability.")],"Humility is being modest."),
  mcq("v3-3",1,"'Looked at in awe' means","observed with great respect and wonder",[("laughed at","Awe is respect and wonder."),("ignored","They looked with wonder.")],"Awe is wonder with respect."),
  mcq("v3-4",2,"Which dash is used in 'pages 50–75'?","en dash",[("em dash","The em dash adds extra information."),("hyphen","A range uses an en dash.")],"The en dash shows a range."),
  mcq("v3-5",2,"Which sentence uses a dash correctly to add extra information?","The exhibition—held in the main hall—features local artists.",[("The exhibition – held in the main hall – features local artists.","Spaces around the dash are not used."),("The exhibition-held in the main hall-features local artists.","The dash for extra information is the em dash, not a hyphen.")],"The em dash adds extra information."),
  mcq("v3-6",2,"Which is the verb?","proDUCE",[("PROduce","This is the noun."),("CONtract","This is the noun.")],"The verb is stressed on the second syllable."),
  tf("v3-7",2,"Spaces should be left on both sides of a dash.",False,"No spaces are used around a dash."),
  mcq("v3-8",3,"Which should a letter thanking grandparents include?","how their wisdom shaped your values",[("a complaint about homework","This does not thank them."),("the school timetable","Not relevant to the thanks.")],"Say how their lessons shaped you."),
  mcq("v3-9",3,"In 'The scores were 2_1', which dash is right?","en dash",[("em dash","The em dash is for extra information."),("no dash is needed","A score range uses an en dash.")],"Scores use the en dash, 2–1.")])
